        }
#endif
        if (DC.dbgHeap == 1) {
            Debug_free_h(m_malloc_addr, m_malloc_heap);
        } else {
            Mem_free_h(m_malloc_addr, m_malloc_heap);
        }
        m_be_flag &= ~2;
    }

#if RE4DC_CABIN_SOURCE
    if (!re4dc_cabin_carriers_reset()) { re4dc_missing("cabin carrier reader before unit reset"); return; }
#endif
    cDataUnit* u;
    u32 i;

    m_aram_free = ARAM_FREE_BASE;
    setAramSort(1);
    m_data_ctrl_flag = 1;
    dbgHeap = 0;
    for (i = 0; i < 32; i++) {
        u = &m_DataUnit[i];
        memclr_asm(u, sizeof(cDataUnit));
        u->m_be_flag &= ~1;
        u->setCondition(0);
        u->setCommand(0, 0, 0);
        u->m_err = 0;
        u->fixMramAddr(0);
    }
    initDummyId();

cDataUnit* u;
int i;

if (m_data_ctrl_flag != 0 && m_nblock_read_stop != 1) {
    while (checkAramSort() == 1) {
    }
    for (i = 0; i < 32; i++) {
        u = &m_DataUnit[i];
        if (u->chk(1) != 0) {
            u->m_err = 0;
            u->checkCommand();
            u->checkCondition();
        }
    }
    checkDummyId();
}

